## Bloques BEGIN...END

En MySQL, la programación almacenada se escribe en bloques delimitados por BEGIN y END.

```sql
-- Bloque anónimo (no se almacena)
BEGIN
  DECLARE total INT;
  SELECT COUNT(*) INTO total FROM alumnos;
  SELECT total AS total_alumnos;
END;
```

## IF...THEN...ELSE

```sql
-- Evaluar la nota de un alumno
BEGIN
  DECLARE v_nota DECIMAL(4,2);
  DECLARE v_resultado VARCHAR(20);

  SELECT nota INTO v_nota FROM notas WHERE id = 1;

  IF v_nota >= 9 THEN
    SET v_resultado = 'Sobresaliente';
  ELSEIF v_nota >= 7 THEN
    SET v_resultado = 'Notable';
  ELSEIF v_nota >= 5 THEN
    SET v_resultado = 'Aprobado';
  ELSE
    SET v_resultado = 'Suspenso';
  END IF;

  SELECT v_nota, v_resultado;
END;
```

## CASE WHEN

```sql
BEGIN
  DECLARE v_ciclo VARCHAR(10);
  DECLARE v_dept VARCHAR(50);

  SELECT ciclo INTO v_ciclo FROM asignaturas WHERE id = 1;

  SET v_dept = CASE v_ciclo
    WHEN 'DAM' THEN 'Desarrollo de Aplicaciones Multiplataforma'
    WHEN 'DAW' THEN 'Desarrollo de Aplicaciones Web'
    WHEN 'ASIR' THEN 'Administración de Sistemas Informáticos'
    ELSE 'Desconocido'
  END;

  SELECT v_ciclo, v_dept;
END;
```

## WHILE loop

```sql
-- Imprimir números del 1 al 10
BEGIN
  DECLARE i INT DEFAULT 1;

  WHILE i <= 10 DO
    SELECT i;
    SET i = i + 1;
  END WHILE;
END;

-- Sumar los primeros N números
BEGIN
  DECLARE i INT DEFAULT 1;
  DECLARE suma INT DEFAULT 0;
  DECLARE n INT DEFAULT 100;

  WHILE i <= n DO
    SET suma = suma + i;
    SET i = i + 1;
  END WHILE;

  SELECT suma AS suma_total;  -- Resultado: 5050
END;
```

## LOOP con LEAVE

```sql
-- LOOP es un bucle infinito que se sale con LEAVE
BEGIN
  DECLARE i INT DEFAULT 1;

  mi_loop: LOOP
    IF i > 10 THEN
      LEAVE mi_loop;  -- Sale del bucle
    END IF;

    SELECT i;
    SET i = i + 1;
  END LOOP mi_loop;
END;

-- ITERATE: salta a la siguiente iteración (como 'continue')
BEGIN
  DECLARE i INT DEFAULT 0;

  mi_loop: LOOP
    SET i = i + 1;

    IF i > 20 THEN
      LEAVE mi_loop;
    END IF;

    IF i % 2 = 0 THEN
      ITERATE mi_loop;  -- Saltar pares
    END IF;

    SELECT i;  -- Solo muestra impares
  END LOOP mi_loop;
END;
```

### Resumen

| Estructura | Uso |
|---|---|
| `IF...THEN...ELSEIF...ELSE...END IF` | Condicional |
| `CASE...WHEN...THEN...ELSE...END CASE` | Condicional con múltiples opciones |
| `WHILE...DO...END WHILE` | Bucle con condición al inicio |
| `LOOP...END LOOP` | Bucle infinito (se sale con LEAVE) |
| `LEAVE` | Sale del bucle (como 'break') |
| `ITERATE` | Salta a la siguiente iteración (como 'continue') |

