  DECLARE v_creditos DECIMAL(4,2);
  DECLARE v_fin BOOLEAN DEFAULT FALSE;
  DECLARE cur CURSOR FOR SELECT creditos FROM asignaturas;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin = TRUE;

  OPEN cur;

  bucle: LOOP
    FETCH cur INTO v_creditos;
    IF v_fin THEN
      LEAVE bucle;
    END IF;
    SET v_suma = v_suma + v_creditos;
  END LOOP bucle;

  CLOSE cur;

  SELECT v_suma AS suma_creditos;
END;
